Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Card is not Orc.Cards.Card played || !object.ReferenceEquals(played, view.Host))
    {
        return;
    }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(played);
    if (runtime is null)
    {
        return;
    }

    for (var i = 0; i < 3; i++)
    {
        var picked = await runtime.SelectAsync(played, new Orc.Game.Effects.EffectSelector("random", null, null, null, null, 1));
        if (picked.Count == 0)
        {
            break;
        }

        await runtime.DamageAsync(picked[0], 1, played, ct);
    }
};
